config.script:
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function blocked(){
  var title=(document.title||'').trim();
  var body=(document.body?document.body.innerText:'')||'';
  return /access denied/i.test(title)
    || (/access denied|you don't have permission|reference #/i.test(body) && /edgesuite|akamai|perimeterx|px-captcha/i.test(body));
}
function ready(){
  var host=(location.host||'');
  var body=(document.body?document.body.innerText:'')||'';
  return /target\.com/i.test(host) && /sign in|create account|cart|categories|deals|target circle|weekly ad/i.test(body);
}
var start=Date.now();
while(document.readyState!=='complete'&&Date.now()-start<45000){await sleep(200);}
var deadline=Date.now()+20000;
while(Date.now()<deadline){
  if(blocked()) throw new Error('Target Access Denied - this proxy IP is blocked. Rotate proxy.');
  if(ready()) return (document.title||'').trim();
  await sleep(500);
}
