function clickText(re){
  var nodes=document.querySelectorAll('button, a, [role=button], input[type=button], input[type=submit]');
  for(var i=0;i<nodes.length;i++){var el=nodes[i];if(!vis(el))continue;var t=(el.innerText||el.textContent||el.value||'').replace(/\s+/g,' ').trim();if(re.test(t)&&t.length<40){try{el.scrollIntoView({block:'center'});}catch(e){}try{el.click();}catch(e){}return true;}}
  return false;
}
